package com.customemoji;

import com.customemoji.model.Lifecycle;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class ChatScrollingManager implements Lifecycle
{
    private static final int LAST_MESSAGE_PADDING = 4;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private EventBus eventBus;

    private int scrollY = 0;
    private int lastScrollHeight = 0;
    private boolean scrollEventFiring;
    private boolean newMessageReceived;
    private boolean lastScrollPosChangedByClient;

    @Override
    public void startUp()
    {
        this.eventBus.register(this);
    }

    @Override
    public void shutDown()
    {
        this.eventBus.unregister(this);
    }

    @Override
    public boolean isEnabled(CustomEmojiConfig config)
    {
        return config.dynamicEmojiSpacing() || config.chatMessageSpacing() != 0;
    }

    @Subscribe
    public void onChatMessage(ChatMessage chatMessage)
    {
        this.newMessageReceived = true;
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event)
    {
        int scriptId = event.getScriptId();
        if (this.isUserScrollEvent(scriptId))
        {
            Object[] args = event.getScriptEvent().getArguments();
            boolean isForChatbox = args.length >= 3 && (int) args[2] == InterfaceID.Chatbox.SCROLLAREA;
            if (isForChatbox)
            {
                this.scrollEventFiring = true;
                this.captureScrollPosition();
                log.debug("CHAT_LASTSCROLLPOS changed by user");
            }
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        int scriptId = event.getScriptId();
        if (this.scrollEventFiring && this.isUserScrollEvent(scriptId))
        {
            this.scrollEventFiring = false;
            this.captureScrollPosition();
        }

        if (scriptId == 223 && !this.scrollEventFiring)
        {
            this.lastScrollPosChangedByClient = true;
            log.debug("CHAT_LASTSCROLLPOS changed by client");
        }
    }

    @Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		switch (event.getIndex())
		{
            case VarClientID.CHAT_VIEW:
                this.scrollToBottom();
                break;
			default:
				break;
		}
	}

    public void captureScrollPosition()
    {
        Widget chatbox = this.client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (chatbox == null)
        {
            return;
        }

        int newValue = chatbox.getScrollY();

        if (newValue == this.scrollY)
        {
            return;
        }

        this.scrollY = newValue;
    }

    public int getScrolledUpPixels()
    {
        Widget chatbox = this.client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (chatbox == null)
        {
            return 0;
        }

        int scrollHeight = chatbox.getScrollHeight();
        int visibleHeight = chatbox.getHeight();

        if (scrollHeight <= visibleHeight)
        {
            return 0;
        }

        return scrollHeight - (visibleHeight + this.scrollY);
    }

    public void scrollToBottom()
    {
        this.clientThread.invokeLater(() ->
        {
            Widget chatbox = this.client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
            if (chatbox == null)
            {
                return;
            }

            int scrollHeight = chatbox.getScrollHeight();
            int visibleHeight = chatbox.getHeight();
            int maxScrollY = Math.max(0, scrollHeight - visibleHeight);

            chatbox.revalidateScroll();

            this.client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Chatbox.CHATSCROLLBAR,
                    InterfaceID.Chatbox.SCROLLAREA, maxScrollY);

            this.captureScrollPosition();
        });
    }

    public void update(Widget widget, int height)
    {
        if (height == 0)
        {
            return;
        }

        if (widget.getDynamicChildren() == null || widget.getDynamicChildren().length < 2)
        {
            return;
        }

        int visibleHeight = widget.getHeight();

        if (height < visibleHeight)
        {
            Widget[] children = PluginUtils.getCombinedChildren(widget);
            PluginUtils.applyStaticYOffset(children, visibleHeight - height - LAST_MESSAGE_PADDING);
        }

        int newScrollHeight = height + LAST_MESSAGE_PADDING;

        widget.setScrollHeight(newScrollHeight);

        int newScrollY;

        if (this.newMessageReceived || !this.lastScrollPosChangedByClient)
        {
            boolean wasAtBottom = false;
            if (this.lastScrollHeight > 0)
            {
                int oldMaxScrollY = this.lastScrollHeight - visibleHeight;
                wasAtBottom = (this.scrollY >= oldMaxScrollY) || (visibleHeight > height);
            }

            if (wasAtBottom)
            {
                int maxScrollY = newScrollHeight - visibleHeight;
                newScrollY = maxScrollY;
            }
            else
            {
                newScrollY = this.scrollY;
            }

            this.newMessageReceived = false;
            this.lastScrollHeight = newScrollHeight;
        }
        else
        {
            int maxScrollY = newScrollHeight - visibleHeight;
            boolean atBottom = this.scrollY >= maxScrollY;

            if (atBottom)
            {
                newScrollY = maxScrollY;
            }
            else
            {
                newScrollY = this.scrollY;
            }
        }

        newScrollY = Math.max(0, Math.min(newScrollY, newScrollHeight - visibleHeight));

        widget.revalidateScroll();

        this.client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Chatbox.CHATSCROLLBAR,
                InterfaceID.Chatbox.SCROLLAREA, newScrollY);

        this.captureScrollPosition();

        this.lastScrollPosChangedByClient = false;
    }

    private boolean isUserScrollEvent(int scriptId)
    {
        return scriptId >= 32 && scriptId <= 36;
    }
}

package com.customemoji;

import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import java.awt.Rectangle;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

import com.customemoji.event.AfterEmojisLoaded;
import com.customemoji.model.Emoji;
import com.customemoji.model.Lifecycle;
import com.customemoji.model.SpacingInfo;

@Slf4j
@Singleton
public class ChatSpacingManager implements Lifecycle
{
    @Inject
    private Client client;

    @Inject
    private CustomEmojiConfig config;

    @Inject
    private ChatScrollingManager chatScrollingManager;

    @Inject
    private ClientThread clientThread;

    @Inject
    private EventBus eventBus;

    private Map<String, Emoji> emojis = new HashMap<>();

    private final List<Rectangle> appliedChatboxYBounds = new ArrayList<>();
    private final List<Rectangle> appliedPmChatYBounds = new ArrayList<>();

    private ScheduledExecutorService debounceExecutor;
    private ScheduledFuture<?> pendingTask = null;

    @Override
    public void startUp()
    {
        this.debounceExecutor = Executors.newSingleThreadScheduledExecutor();
        this.eventBus.register(this);
    }

    @Subscribe
    public void onAfterEmojisLoaded(AfterEmojisLoaded event)
    {
        this.emojis = event.getEmojis();
        this.clearStoredPositions();
        this.applyChatSpacing();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        this.clientThread.invokeAtTickEnd(this::clearStoredPositions);
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (event.getScriptId() == 84)
        {
            this.applyChatSpacing();
        }
    }

    @Subscribe
    public void onVarClientIntChanged(VarClientIntChanged event)
    {
        switch (event.getIndex())
        {
            case VarClientID.CHAT_VIEW:
                this.clearStoredPositions();
                // intentional fallthrough
            case VarClientID.MESLAYERMODE:
            case VarClientID.CHAT_LASTREBUILD:
            case VarClientID.CHAT_FORCE_CHATBOX_REBUILD:
                this.applyChatSpacing();
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals("custom-emote"))
        {
            return;
        }

        switch (event.getKey())
        {
            case CustomEmojiConfig.KEY_DYNAMIC_EMOJI_SPACING:
            case CustomEmojiConfig.KEY_CHAT_MESSAGE_SPACING:
                this.applyChatSpacing();
                break;
            default:
                break;
        }
    }

    public void clearStoredPositions()
    {
        this.appliedChatboxYBounds.clear();
        this.appliedPmChatYBounds.clear();
    }

    public void applyChatSpacing()
    {
        if (this.debounceExecutor == null || this.debounceExecutor.isShutdown())
        {
            return;
        }

        boolean isFirstCall = this.pendingTask == null || this.pendingTask.isDone();

        if (!isFirstCall)
        {
            this.pendingTask.cancel(false);
        }

        if (isFirstCall)
        {
            this.clientThread.invokeAtTickEnd(this::executeApplyChatSpacing);
        }

        this.pendingTask = this.debounceExecutor.schedule(
            () -> this.clientThread.invokeAtTickEnd(this::executeApplyChatSpacing),
            10,
            TimeUnit.MILLISECONDS
        );
    }

    private void executeApplyChatSpacing()
    {
        Widget chatbox = this.client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        this.processWidget(chatbox, false);
    }

    @Override
    public void shutDown()
    {
        this.eventBus.unregister(this);
        if (this.debounceExecutor != null)
        {
            this.debounceExecutor.shutdownNow();
            this.debounceExecutor = null;
        }
        this.clearStoredPositions();
    }

    @Override
    public boolean isEnabled(CustomEmojiConfig config)
    {
        return config.dynamicEmojiSpacing() || config.chatMessageSpacing() != 0;
    }

    private void processWidget(Widget widget, boolean invert)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        Widget[] children = this.getCombinedChildren(widget);
        int height = this.adjustChildren(children, invert);

        if (!invert)
        {
            this.chatScrollingManager.update(widget, height);
        }
    }

    private Widget[] getCombinedChildren(Widget parent)
    {
        Widget[] dynamicChildren = this.getChildren(parent::getDynamicChildren);
        Widget[] staticChildren = this.getChildren(parent::getStaticChildren);

        if (dynamicChildren == null)
        {
            dynamicChildren = new Widget[0];
        }
        if (staticChildren == null)
        {
            staticChildren = new Widget[0];
        }

        Widget[] allChildren = new Widget[dynamicChildren.length + staticChildren.length];
        System.arraycopy(dynamicChildren, 0, allChildren, 0, dynamicChildren.length);
        System.arraycopy(staticChildren, 0, allChildren, dynamicChildren.length, staticChildren.length);
        return allChildren;
    }

    private int adjustChildren(Widget[] children, boolean invert)
    {
        if (children == null)
        {
            return 0;
        }

        List<List<Widget>> messageList = PluginUtils.groupWidgetsByOriginalYPosition(children);

        int startIndex = Math.max(0, messageList.size() - this.config.messageProcessLimit());
        int maxY = 0;

        if (this.config.messageProcessLimit() == 0)
        {
            startIndex = 0; // 0 = unlimited
        }

        if (startIndex > 0 && !messageList.isEmpty())
        {
            List<Widget> prevMessage = messageList.get(startIndex-1);
            if (!prevMessage.isEmpty())
            {
                Widget widget = prevMessage.get(0);
                maxY = widget.getOriginalY() + widget.getOriginalHeight();
            }
        }

        for (int i = startIndex; i < messageList.size(); i++)
        {
            List<Widget> message = messageList.get(i);

            if (!message.isEmpty() && invert && maxY == 0)
            {
                Widget widget = message.get(0);
                int originalY = widget.getOriginalY();
                maxY = originalY;
            }

            Rectangle messageBounds = this.getMessageBounds(message, maxY, invert);

            for (Widget messagePart : message)
            {
                messagePart.setOriginalY(messageBounds.y);
                messagePart.revalidate();
            }

            boolean onLatestMessage = i == messageList.size() - 1;
            if (onLatestMessage)
            {
                maxY += messageBounds.height; // Don't need extra spacing below latest message
            }
            else
            {
                maxY += messageBounds.height + this.config.chatMessageSpacing();
            }
        }

        return maxY;
    }

    private Rectangle getMessageBounds(List<Widget> messageWidgets, int startY, boolean invert)
    {
        boolean dynamicSpacing = this.config.dynamicEmojiSpacing();
        IndexedSprite[] modIcons = this.config.dynamicEmojiSpacing() ? this.client.getModIcons() : null;
        EmojiPositionCalculator.DimensionLookup dimensionLookup = dynamicSpacing
           ? imageId -> PluginUtils.getEmojiDimension(modIcons, imageId)
           : null;

        Set<Integer> customEmojiIds = Collections.emptySet();
        if (dynamicSpacing)
        {
           Map<Integer, Emoji> emojiLookup = PluginUtils.buildEmojiLookup(() -> this.emojis);
           customEmojiIds = emojiLookup.keySet();
        }

        int maxAboveSpacing = 0;
        int maxWidgetHeight = 0;
        int maxBelowSpacing = 0;
        int totalWidth = 0;

        for (Widget child : messageWidgets)
        {

            SpacingInfo spacing = EmojiPositionCalculator.calculateSpacingForWidget(child, dimensionLookup, customEmojiIds);
            maxAboveSpacing = Math.max(maxAboveSpacing, spacing.getAboveSpacing());
            maxWidgetHeight = Math.max(maxWidgetHeight, child.getHeight());
            maxBelowSpacing = Math.max(maxBelowSpacing, spacing.getBelowSpacing());
            totalWidth += child.getWidth();
        }

        Rectangle bounds = new Rectangle();
        if (invert)
        {
            bounds.y = startY + maxBelowSpacing;
            bounds.height = maxAboveSpacing + maxWidgetHeight + maxBelowSpacing;
            bounds.width = totalWidth;
        }
        else
        {
            bounds.y = startY + maxAboveSpacing;
            bounds.height = maxAboveSpacing + maxWidgetHeight + maxBelowSpacing;
            bounds.width = totalWidth;
        }

        return bounds;
    }

    private Widget[] getChildren(Supplier<Widget[]> childrenSupplier)
    {
        Widget[] children = childrenSupplier.get();
        if (children == null)
        {
            return new Widget[0];
        }

        return Arrays.copyOf(children, children.length);
    }
}

package com.customemoji;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(CustomEmojiConfig.KEY_CONFIG_GROUP)
public interface CustomEmojiConfig extends Config
{
	String KEY_CONFIG_GROUP = "custom-emote";

	// Display section
	String KEY_SPLIT_PRIVATE_CHAT = "split_private_chat";
	String KEY_DYNAMIC_EMOJI_SPACING = "dynamic_emoji_spacing";
	String KEY_CHAT_MESSAGE_SPACING = "chat_message_spacing";
	String KEY_MESSAGE_PROCESS_LIMIT = "message_process_limit";
	String KEY_MAX_IMAGE_HEIGHT = "max_image_height";
	String KEY_ANIMATION_LOADING_MODE = "animation_loading_mode";
	String KEY_FILTER_DISABLED_EMOJI_MESSAGES = "filter_disabled_emoji_messages";

	// UI Components section
	String KEY_SHOW_SIDE_PANEL = "show_panel";
	String KEY_SHOW_EMOJI_TOOLTIPS = "show_emoji_tooltips";
	String KEY_OVERLAY_MAX_SUGGESTIONS = "overlay_max_suggestions";
	String KEY_NEW_MESSAGE_INDICATOR_MODE = "new_message_indicator_mode";

	// GitHub section
	String KEY_GITHUB_ADDRESS = "github_repo_address";

	// Soundoji section
	String KEY_VOLUME = "volume";

	// Seasonal section
	String KEY_SEASONAL_HALLOWEEN_ENABLED = "seasonal_halloween_enabled";
	String KEY_SEASONAL_CHRISTMAS_ENABLED = "seasonal_christmas_enabled";

	// Experimental section
	String KEY_NEW_EMOJI_LOADER = "new_emoji_loader";

	// Hidden
	String KEY_DISABLED_EMOJIS = "disabled_emojis";
	String KEY_RESIZING_DISABLED_EMOJIS = "resizing_disabled_emojis";

	@ConfigSection(
		name = "Display",
		description = "General emoji display settings",
		position = 0
	)
	String DISPLAY_SECTION = "displaySection";

	@ConfigItem(
		keyName = KEY_DYNAMIC_EMOJI_SPACING,
		name = "Dynamic Spacing",
		description = "Dynamically add extra spacing for lines with tall emojis.",
		section = DISPLAY_SECTION,
		position = 1
	)
	default boolean dynamicEmojiSpacing()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_CHAT_MESSAGE_SPACING,
		name = "Extra Spacing",
		description = "Extra vertical spacing between chat messages (in pixels).",
		section = DISPLAY_SECTION,
		position = 2
	)
	@Range(min = 0, max = 20)
	default int chatMessageSpacing()
	{
		return 0;
	}

	@ConfigItem(
		keyName = KEY_MESSAGE_PROCESS_LIMIT,
		name = "Message Process Limit",
		description = "Maximum number of recent messages to apply spacing to. Lower values improve performance with long chat history.  <b>(0 = unlimited)</b>",
		section = DISPLAY_SECTION,
		position = 3
	)
	@Range(min = 0, max = 500)
	default int messageProcessLimit()
	{
		return 50;
	}

	@ConfigItem(
		keyName = KEY_MAX_IMAGE_HEIGHT,
		name = "Max Emoji Height",
		description = "Maximum height (in pixels) for emojis with resizing enabled.",
		section = DISPLAY_SECTION,
		position = 4
	)
	@Range(min = 0, max = 100)
	default int maxImageHeight()
	{
		return 24;
	}

	@ConfigItem(
		keyName = KEY_ANIMATION_LOADING_MODE,
		name = "Animation Mode",
		description = "<b>Off:</b> Animations disabled.<br>" +
					  "<b>Lazy:</b> Loads frames progressively as needed. <b>[Recommended]</b><br>" +
					  "<b>Eager:</b> Loads all frames immediately.",
		section = DISPLAY_SECTION,
		position = 5
	)
	default AnimationLoadingMode animationLoadingMode()
	{
		return AnimationLoadingMode.LAZY;
	}

	@ConfigItem(
		keyName = KEY_FILTER_DISABLED_EMOJI_MESSAGES,
		name = "Message Filter",
		description = "<b>Off:</b> No filtering applied.<br>" +
			"<b>Lenient:</b> Hide messages containing only disabled emojis.<br>" +
			"<b>Strict:</b> Hide messages containing any disabled emoji.",
		section = DISPLAY_SECTION,
		position = 5
	)
	default DisabledEmojiFilterMode disabledEmojiFilterMode()
	{
		return DisabledEmojiFilterMode.OFF;
	}

	@ConfigSection(
		name = "UI Components",
		description = "Plugin panels, tooltips, and overlays",
		position = 1
	)
	String UI_COMPONENTS_SECTION = "uiComponentsSection";

	@ConfigItem(
		keyName = KEY_SHOW_SIDE_PANEL,
		name = "Show Sidebar Panel",
		description = "Show the emoji panel in the sidebar.",
		section = UI_COMPONENTS_SECTION,
		position = 0
	)
	default boolean showPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SHOW_EMOJI_TOOLTIPS,
		name = "Show Tooltips",
		description = "Display emoji name when hovering over emojis in chat.",
		section = UI_COMPONENTS_SECTION,
		position = 1
	)
	default boolean showEmojiTooltips()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_OVERLAY_MAX_SUGGESTIONS,
		name = "Max Suggestions",
		description = "Maximum number of emoji suggestions to display. <b>(0 = disabled)</b>",
		section = UI_COMPONENTS_SECTION,
		position = 3
	)
	default int maxImageSuggestions()
	{
		return 10;
	}

	@ConfigItem(
		keyName = KEY_NEW_MESSAGE_INDICATOR_MODE,
		name = "New Message Indicator",
		description = "<b>Off:</b> No indicator shown.<br>" +
					  "<b>Banner:</b> Shows a banner at the bottom of the chat.<br>" +
					  "<b>Arrow:</b> Shows a circular arrow button at the bottom-right.<br><br>" +
					  "When clicked, the chat will scroll to the latest message.<br>" +
					  "<b>Note:</b> The indicator is not clickable when <u>Transparent chatbox</u> and<br>" +
					  "<u>Click through transparent chatbox</u> are enabled.",
		section = UI_COMPONENTS_SECTION,
		position = 4
	)
	default NewMessageIndicatorMode newMessageIndicatorMode()
	{
		return NewMessageIndicatorMode.OFF;
	}

	@ConfigSection(
		name = "GitHub Emoji Pack",
		description = "Download emojis from a GitHub repository",
		position = 2
	)
	String GITHUB_SECTION = "githubSection";

	@ConfigItem(
		keyName = KEY_GITHUB_ADDRESS,
		name = "Repository",
		description = "GitHub repository in format 'user/repo' or 'user/repo/tree/branch'. Leave empty to disable.",
		section = GITHUB_SECTION,
		position = 0
	)
	default String githubRepoUrl()
	{
		return "";
	}

	@ConfigSection(
		name = "Soundoji",
		description = "Sound-enabled emoji settings",
		position = 3
	)
	String SOUNDOJI_SECTION = "overlaySection";

	@ConfigItem(
		keyName = KEY_VOLUME,
		name = "Volume",
		description = "Soundoji playback volume. [0-100]",
		section = SOUNDOJI_SECTION,
		position = 0
	)
	@Range(min = 0, max = 100)
	default int volume()
	{
		return 70;
	}

	@ConfigSection(
		name = "Seasonal Emojis",
		description = "Holiday versions of your emojis",
		position = 4
	)
	String SEASONAL_SECTION = "seasonalSection";

	@ConfigItem(
		keyName = KEY_SEASONAL_HALLOWEEN_ENABLED,
		name = "Halloween",
		description = "Use emojis from the <b>Seasonal/Halloween</b> folder from <b>October 1</b> to <b>November 1</b>.",
		section = SEASONAL_SECTION,
		position = 0
	)
	default boolean halloweenEmojisEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SEASONAL_CHRISTMAS_ENABLED,
		name = "Christmas",
		description = "Use emojis from the <b>Seasonal/Christmas</b> folder from <b>December 1</b> to <b>January 1</b>.",
		section = SEASONAL_SECTION,
		position = 1
	)
	default boolean christmasEmojisEnabled()
	{
		return true;
	}

	/*@ConfigSection(
		name = "Experimental",
		description = "Experimental features (may be unstable)",
		position = 4
	)
	String EXPERIMENTAL_SECTION = "experimentalSection";*/

	@ConfigItem(
		keyName = KEY_DISABLED_EMOJIS,
		name = "",
		description = "",
		hidden = true
	)
	default String disabledEmojis()
	{
		return "";
	}

	@ConfigItem(
		keyName = KEY_RESIZING_DISABLED_EMOJIS,
		name = "",
		description = "",
		hidden = true
	)
	default String resizingDisabledEmojis()
	{
		return "";
	}

	enum AnimationLoadingMode
	{
		OFF("Off"),
		LAZY("Lazy"),
		EAGER("Eager");

		private final String name;

		AnimationLoadingMode(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
