import com.customemoji.io.SoundojiLoader;
import com.customemoji.model.Lifecycle;
import com.customemoji.panel.EmojiPanelManager;
import com.customemoji.renderer.ChatEmojiRenderer;
import com.customemoji.renderer.NewMessageBannerRenderer;
import com.customemoji.renderer.OverheadEmojiRenderer;
import com.customemoji.renderer.SplitPrivateChatEmojiRenderer;
import com.google.inject.Inject;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

public class LifecycleManager
{
	private final Map<Lifecycle, Boolean> managedObjects = new LinkedHashMap<>();

	@Inject
	private EventBus eventBus;

	@Inject
	private CustomEmojiConfig config;

	@Inject
	public LifecycleManager
	(
		AnimationManager animationManager,
		GitHubEmojiDownloader githubDownloader,
		EmojiUsageRecorder usageRecorder,
		CustomEmojiOverlay overlay,
		CustomEmojiTooltip tooltip,
		NewMessageBannerRenderer newMessageBannerRenderer,
		ChatSpacingManager chatSpacingManager,
		ChatScrollingManager chatScrollingManager,
		SeasonalEmojiManager seasonalEmojiManager,
		EmojiLoader emojiLoader,
		SoundojiLoader soundojiLoader,
		SoundojiPlayer soundojiPlayer,
		EmojiMessageManager messageManager,
		ChatEmojiRenderer chatEmojiRenderer,
		OverheadEmojiRenderer overheadEmojiRenderer,
		SplitPrivateChatEmojiRenderer splitPrivateChatEmojiRenderer,
		EmojiPanelManager emojiPanelManager
	)
	{
		this.managedObjects.put(animationManager, false);
		this.managedObjects.put(githubDownloader, false);
		this.managedObjects.put(usageRecorder, false);
		this.managedObjects.put(overlay, false);
		this.managedObjects.put(tooltip, false);
		this.managedObjects.put(newMessageBannerRenderer, false);
		this.managedObjects.put(chatSpacingManager, false);
		this.managedObjects.put(chatScrollingManager, false);
		this.managedObjects.put(seasonalEmojiManager, false);
		this.managedObjects.put(emojiLoader, false);
		this.managedObjects.put(soundojiLoader, false);
		this.managedObjects.put(soundojiPlayer, false);
		this.managedObjects.put(messageManager, false);
		this.managedObjects.put(chatEmojiRenderer, false);
		this.managedObjects.put(overheadEmojiRenderer, false);
		this.managedObjects.put(splitPrivateChatEmojiRenderer, false);
		this.managedObjects.put(emojiPanelManager, false);
	}

	public void startUp()
	{
		this.eventBus.register(this);
		this.updateManagedObjects();
	}

	public void shutDown()
	{
		this.eventBus.unregister(this);

		List<Map.Entry<Lifecycle, Boolean>> entries = new ArrayList<>(this.managedObjects.entrySet());
		Collections.reverse(entries);

		for (Map.Entry<Lifecycle, Boolean> entry : entries)
		{
			boolean isRunning = entry.getValue();

			if (isRunning)
			{
				entry.getKey().shutDown();
				entry.setValue(false);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("custom-emote"))
		{
			return;
		}

		this.updateManagedObjects();
	}

	private void updateManagedObjects()
	{
		for (Map.Entry<Lifecycle, Boolean> entry : this.managedObjects.entrySet())
		{
			boolean isEnabled = entry.getKey().isEnabled(this.config);
			boolean isActive = entry.getValue();

			if (isEnabled && !isActive)
			{
				entry.getKey().startUp();
				entry.setValue(true);
			}
			else if (!isEnabled && isActive)
			{
				entry.getKey().shutDown();
				entry.setValue(false);
			}
		}
	}
}

package com.customemoji.service;

import com.customemoji.CustomEmojiConfig;
import com.customemoji.model.Holiday;
import com.customemoji.model.Lifecycle;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.MonthDay;
import java.time.ZoneId;
import java.util.EnumSet;
import java.util.Set;

@Singleton
public class SeasonalEmojiManager implements Lifecycle
{
	private final CustomEmojiConfig config;

	@Inject
	public SeasonalEmojiManager(CustomEmojiConfig config)
	{
		this.config = config;
	}

	@Override
	public void startUp()
	{
		// Do nothing
	}

	@Override
	public void shutDown()
	{
		// Do nothing
	}

	@Override
	public boolean isEnabled(CustomEmojiConfig config)
	{
		return config.halloweenEmojisEnabled() || config.christmasEmojisEnabled();
	}

	public static boolean isSeasonalConfigKey(String key)
	{
		boolean isHalloweenKey = CustomEmojiConfig.KEY_SEASONAL_HALLOWEEN_ENABLED.equals(key);
		boolean isChristmasKey = CustomEmojiConfig.KEY_SEASONAL_CHRISTMAS_ENABLED.equals(key);

		return isHalloweenKey || isChristmasKey;
	}

	public Set<Holiday> activeHolidays()
	{
		return this.activeHolidays(MonthDay.now(ZoneId.systemDefault()));
	}

	public Set<Holiday> activeHolidays(MonthDay date)
	{
		Set<Holiday> activeHolidays = EnumSet.noneOf(Holiday.class);

		for (Holiday holiday : Holiday.values())
		{
			if (this.isActive(holiday, date))
			{
				activeHolidays.add(holiday);
			}
		}

		return activeHolidays;
	}

	private boolean isActive(Holiday holiday, MonthDay date)
	{
		boolean isEnabled = this.isEnabled(holiday);
		if (!isEnabled)
		{
			return false;
		}

		return holiday.includes(date);
	}

	private boolean isEnabled(Holiday holiday)
	{
		switch (holiday)
		{
		case HALLOWEEN:
			return this.config.halloweenEmojisEnabled();
		case CHRISTMAS:
			return this.config.christmasEmojisEnabled();
		default:
			return false;
		}
	}
}

package com.customemoji.service;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.customemoji.CustomEmojiConfig;
import com.customemoji.event.AfterSoundojisLoaded;
import com.customemoji.event.SoundojiTriggered;
import com.customemoji.model.Lifecycle;
import com.customemoji.model.Soundoji;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class SoundojiPlayer implements Lifecycle
{
	private static final float NOISE_FLOOR = -60f;

	@Inject
	private EventBus eventBus;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private CustomEmojiConfig config;

	private Map<String, Soundoji> soundojis = new ConcurrentHashMap<>();

	@Override
	public void startUp()
	{
		this.eventBus.register(this);
	}

	@Override
	public void shutDown()
	{
		this.eventBus.unregister(this);
		this.soundojis.clear();
	}

	@Override
	public boolean isEnabled(CustomEmojiConfig config)
	{
		return config.volume() != 0;
	}

	@Subscribe
	public void onAfterSoundojisLoaded(AfterSoundojisLoaded event)
	{
		this.soundojis = event.getSoundojis();
	}

	@Subscribe
	public void onSoundojiTriggered(SoundojiTriggered event)
	{
		Soundoji soundoji = this.soundojis.get(event.getTrigger().toLowerCase());
		if (soundoji == null)
		{
			return;
		}

		try
		{
			float gain = SoundojiPlayer.volumeToGain(this.config.volume());
			this.audioPlayer.play(soundoji.getFile(), gain);
		}
		catch (Exception e)
		{
			log.error("Failed to play soundoji: " + soundoji.getText(), e);
		}
	}

	static float volumeToGain(int volume100)
	{
		// Graph of the function
		// https://www.desmos.com/calculator/wdhsfbxgeo

		// clamp to 0-100
		float volume = Math.min(100, volume100);

		// convert linear volume 0-100 to log control
		if (volume <= 0.1)
		{
			return NOISE_FLOOR;
		}

		return (float) (10 * (Math.log(volume / 100)));
	}
}

